    if (rst) begin
        rvalid_reg <= 1'b0;
        rdata_reg <= 32'b0;
        rresp_reg <= 2'b0;
    end else begin
        if (arvalid && !rvalid_reg) begin
            rvalid_reg <= 1'b1;
            if (araddr[5]) begin
                rdata_reg <= 32'b0;
                rresp_reg <= 2'b10;
